SELECT COUNT(*) FROM users as u, postHistory as ph, posts as p WHERE p.OwnerUserId = u.Id AND ph.UserId = u.Id AND u.Views>=0 AND u.DownVotes>=0 AND u.DownVotes<=0 AND u.UpVotes>=0 AND u.UpVotes<=37 AND ph.CreationDate>='2010-09-06 11:41:43'::timestamp AND ph.CreationDate<='2014-09-03 16:41:18'::timestamp AND p.Score>=-1 AND p.ViewCount>=0 AND p.ViewCount<=39097 AND p.AnswerCount>=0 AND p.CommentCount>=0 AND p.CommentCount<=11 AND p.FavoriteCount<=10 AND p.CreationDate>='2010-08-13 02:18:09'::timestamp AND p.CreationDate<='2014-09-09 10:20:27'::timestamp;